  | "Mn" -> Some gc_mn
  | "Mc" -> Some gc_mc
  | "Me" -> Some gc_me
  | "Nd" -> Some gc_nd
  | "Nl" -> Some gc_nl
  | "No" -> Some gc_no
  | "Pc" -> Some gc_pc
  | "Pd" -> Some gc_pd
  | "Ps" -> Some gc_ps
  | "Pe" -> Some gc_pe
  | "Pi" -> Some gc_pi
  | "Pf" -> Some gc_pf
  | "Po" -> Some gc_po
  | "Sm" -> Some gc_sm
  | "Sc" -> Some gc_sc
  | "Sk" -> Some gc_sk
  | "So" -> Some gc_so
  | "Zs" -> Some gc_zs
  | "Zl" -> Some gc_zl
